const input = $input.first().json;
if (input.mode === 'live' && input.fixture_json === '') {
  return [{ json: { mode: 'live' } }];
}
if (input.mode !== 'fixture') {
  throw new Error('invalid_ingest_mode');
}
if (typeof input.fixture_json !== 'string' || input.fixture_json.length === 0 || input.fixture_json.length > 2097152) throw new Error('invalid_fixture_feed');
let feed;
try {
  feed = JSON.parse(input.fixture_json);
} catch {
  throw new Error('invalid_fixture_feed');
}
return [{ json: { mode: 'fixture', source: 'demo.usgs', feed } }];

const input = $input.first().json;
if ((input.source !== 'usgs' && input.source !== 'demo.usgs') || !input.feed || input.feed.type !== 'FeatureCollection' || !Array.isArray(input.feed.features)) {
  throw new Error('invalid_feed');
}
const features = input.feed.features;
if (features.length > 1000) throw new Error('feed_too_many_features');
let size;
try {
  size = encodeURIComponent(JSON.stringify(input.feed)).replace(/%[0-9A-F]{2}/gi, 'x').length;
} catch {
  throw new Error('invalid_feed');
}
if (size > 2097152) throw new Error('feed_too_large');
const events = [];
const diagnostics = [];
for (const feature of features) {
  const id = feature && feature.id;
  const safeId = typeof id === 'string' && /^[!-~]{1,128}$/.test(id) ? id : null;
  if (!safeId) {
    diagnostics.push({ code: 'invalid_external_id' });
    continue;
  }
  const properties = feature && feature.properties;
  if (feature.type !== 'Feature' || !properties || properties.type !== 'earthquake') {
    diagnostics.push({ code: 'unsupported_feature', external_id: safeId });
    continue;
  }
  const mag = properties && properties.mag;
  if (typeof mag !== 'number' || !Number.isFinite(mag)) {
    diagnostics.push({ code: 'invalid_magnitude', external_id: safeId });
    continue;
  }
  const ms = properties.time;
  if (typeof ms !== 'number' || !Number.isFinite(ms) || !Number.isInteger(ms) || ms < -62135596800000 || ms > 253402300799999) {
    diagnostics.push({ code: 'invalid_occurrence', external_id: safeId });
    continue;
  }
  const occurred = new Date(ms).toISOString();
  const place = typeof properties.place === 'string' ? properties.place.replace(/[\x00-\x1f\x7f-\x9f]/g, ' ').trim().slice(0, 200) : '';
  const fallback = place ? `M ${mag} - ${place}` : `M ${mag} - Earthquake`;
  const rawTitle = typeof properties.title === 'string' && properties.title.trim() ? properties.title : fallback;
  const title = rawTitle.replace(/[\x00-\x1f\x7f-\x9f]/g, ' ').trim().slice(0, 300).trim() || 'Earthquake';
  let url = null;
  if (typeof properties.url === 'string' && properties.url.length <= 2048 && /^https?:\/\/[^\s\x00-\x1f\x7f-\x9f]+$/.test(properties.url)) {
    const authority = /^https?:\/\/([^\/?#]+)/.exec(properties.url)?.[1];
    if (authority && /^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/.test(authority)) url = properties.url;
  }
  events.push({ contract_version: 1, source: input.source, external_id: safeId, event_type: 'earthquake', occurred_at: occurred, title, source_url: url, data: { magnitude: mag } });
}
return [{ json: { events, diagnostics } }];

const output = [];
const safeEvent = event => ({
  source: typeof event?.source === 'string' && /^(?:usgs|demo\.usgs)$/.test(event.source) ? event.source : undefined,
  external_id: typeof event?.external_id === 'string' && /^[!-~]{1,128}$/.test(event.external_id) ? event.external_id : undefined,
});
const diagnostic = (code, event, alertId) => ({ json: { channel: 'diagnostic', code, ...safeEvent(event), ...(alertId ? { alert_id: alertId } : {}) } });
const validAlertId = id => typeof id === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id) && !/^0{8}-0{4}-0{4}-0{4}-0{12}$/i.test(id);
const validEmail = value => typeof value === 'string' && value.length <= 254 && /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*@[A-Za-z0-9]+(?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9]+(?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/.test(value);
for (const item of $input.all()) {
  const { event, alerts } = item.json ?? {};
  const magnitude = event?.data?.magnitude;
  if (event?.contract_version !== 1 || typeof event?.source !== 'string' || !/^(?:usgs|demo\.usgs)$/.test(event.source) || typeof event?.external_id !== 'string' || !/^[!-~]{1,128}$/.test(event.external_id) || event?.event_type !== 'earthquake' || typeof magnitude !== 'number' || !Number.isFinite(magnitude) || !Array.isArray(alerts)) {
    output.push(diagnostic('invalid_event_or_envelope', event));
    continue;
  }
  for (const alert of alerts) {
    if (!alert || alert.enabled !== true) continue;
    if (!validAlertId(alert.id)) { output.push(diagnostic('invalid_alert_id', event)); continue; }
    const id = alert.id;
    if (alert.event_type !== 'earthquake' || alert.condition_field !== 'magnitude' || alert.condition_operator !== 'gte' || alert.condition_value_type !== 'number') {
      output.push(diagnostic('unsupported_condition', event, id));
      continue;
    }
    if (typeof alert.condition_value !== 'number' || !Number.isFinite(alert.condition_value)) {
      output.push(diagnostic('invalid_threshold', event, id));
      continue;
    }
    if (magnitude < alert.condition_value) continue;
    const notification = (channel, destination) => ({ json: { event, alert_id: id, alert_name: alert.name, channel, destination } });
    const slack = alert.slack_destination;
    if (slack !== null && slack !== undefined) {
      if (typeof slack !== 'string' || !/^[A-Z0-9]{2,80}$/.test(slack)) output.push(diagnostic('invalid_slack_destination', event, id));
      else output.push(notification('slack', slack));
    }
    const email = alert.email_destination;
    if (email !== null && email !== undefined) {
      if (!validEmail(email)) output.push(diagnostic('invalid_email_destination', event, id));
      else output.push(notification('email', email));
    }
  }
}
return output;

const output = [];
const escape = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
for (const item of $input.all()) {
  const { event, alert_name: alertName, channel, destination } = item.json ?? {};
  const occurred = typeof event?.occurred_at === 'string' && Number.isFinite(Date.parse(event.occurred_at)) ? new Date(event.occurred_at).toISOString() : '';
  if (channel !== 'slack' || typeof destination !== 'string' || !/^[A-Z0-9]{2,80}$/.test(destination) || typeof event?.external_id !== 'string' || !/^[!-~]{1,128}$/.test(event.external_id) || typeof event?.title !== 'string' || !occurred || typeof event?.data?.magnitude !== 'number' || !Number.isFinite(event.data.magnitude)) {
    throw new Error('invalid_slack_notification');
  }
  const name = typeof alertName === 'string' && !/[\u0000-\u001f\u007f-\u009f]/.test(alertName) ? alertName.replace(/\s+/g, ' ').trim().slice(0, 120) : '';
  const synthetic = event.source === 'demo.usgs' ? '[SYNTHETIC] ' : '';
  const lines = [`${synthetic}Earthquake M ${event.data.magnitude}: ${escape(event.title)}`, `Occurred: ${occurred}`, `Source: ${escape(event.source)}`, ...(name ? [`Alert: ${escape(name)}`] : [])];
  const text = lines.join('\n');
  output.push({ json: { destination, text } });
}
return output;

const output = [];
const mailbox = value => typeof value === 'string' && value.length <= 254 && /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*@[A-Za-z0-9]+(?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9]+(?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/.test(value);
const clean = (value, limit) => typeof value === 'string' ? value.replace(/[\u0000-\u001f\u007f-\u009f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, limit) : '';
for (const [index, item] of $input.all().entries()) {
  const { event, alert_name: alertName, channel, destination } = item.json ?? {};
  const magnitude = event?.data?.magnitude;
  const title = clean(event?.title, 160);
  const occurred = typeof event?.occurred_at === 'string' && Number.isFinite(Date.parse(event.occurred_at)) ? new Date(event.occurred_at).toISOString() : '';
  if (channel !== 'email' || !mailbox(destination) || event?.contract_version !== 1 || !/^(?:usgs|demo\.usgs)$/.test(event?.source) || event?.event_type !== 'earthquake' || !title || !occurred || typeof magnitude !== 'number' || !Number.isFinite(magnitude)) {
    throw new Error('invalid_email_notification');
  }
  const name = typeof alertName === 'string' && !/[\u0000-\u001f\u007f-\u009f]/.test(alertName) ? clean(alertName, 120) : '';
  let sourceUrl = '';
  if (typeof event.source_url === 'string' && event.source_url.length <= 2048 && /^https?:\/\/[^\s\u0000-\u001f\u007f-\u009f]+$/.test(event.source_url)) {
    const authority = /^https?:\/\/([^\/?#]+)/.exec(event.source_url)?.[1];
    const parts = /^([^:]+)(?::([0-9]{1,5}))?$/.exec(authority ?? '');
    const host = parts?.[1];
    const port = parts?.[2];
    if (host && host.length <= 253 && host.split('.').every(label => /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/.test(label)) && (!port || (Number(port) >= 1 && Number(port) <= 65535))) sourceUrl = event.source_url;
  }
  const synthetic = event.source === 'demo.usgs' ? '[SYNTHETIC] ' : '';
  const lines = [`${synthetic}Sonrisa earthquake alert`, ...(name ? [`Alert: ${name}`] : []), `Earthquake: M ${magnitude} — ${title}`, `Occurred: ${occurred}`, `Source: ${event.source === 'usgs' ? 'USGS' : 'USGS (synthetic test)'}`, ...(sourceUrl ? [`Event URL: ${sourceUrl}`] : [])];
  output.push({ json: { destination, subject: `${synthetic}Sonrisa alert: ${title}`, text: lines.join('\n') }, pairedItem: { item: index } });
}
return output;

const output = [];
for (const [index, item] of $input.all().entries()) {
  const origin = $('Process each notification').item.json;
  const result = item.json ?? {};
  const destination = origin?.destination;
  const accepted = result.accepted;
  const rejected = result.rejected;
  const envelope = result.envelope;
  const confirmed = result && typeof result === 'object' && typeof destination === 'string' && destination.length > 0 && !('error' in result) && !('errors' in result) &&
    Array.isArray(accepted) && accepted.length === 1 && accepted[0] === destination &&
    Array.isArray(rejected) && rejected.length === 0 &&
    (envelope === undefined || (envelope && Array.isArray(envelope.to) && envelope.to.length === 1 && envelope.to[0] === destination));
  const source = origin?.event?.source;
  const externalId = origin?.event?.external_id;
  const alertId = origin?.alert_id;
  output.push({ json: { channel: 'diagnostic', code: confirmed ? 'email_accepted' : 'email_outcome_unconfirmed_discarded',
    ...(typeof source === 'string' && /^(?:usgs|demo\.usgs)$/.test(source) ? { source } : {}),
    ...(typeof externalId === 'string' && /^[!-~]{1,128}$/.test(externalId) ? { external_id: externalId } : {}),
    ...(typeof alertId === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(alertId) ? { alert_id: alertId } : {})
  }, pairedItem: { item: index } });
}
return output;
